// One wire name for the client frame: the alias is gone, and the frame the validator returns is the exported shape.

describe('the websocket frame validator', () => {
  it('accepts user_message and returns the frame the exported union describes', () => {
    const result = validateMessage({type: 'user_message', content: 'hello'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('rejects send_message, which is no longer a wire name', () => {
    const result = validateMessage({type: 'send_message', content: 'hello'});

    expect(result).toEqual({valid: false, error: 'Unknown message type: send_message'});
  });

  it('drops any field the frame does not define, rather than forwarding it', () => {
    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  // [validated by: accepts a bare list_sessions frame and rejects malformed pagination without calling listFor](../../specs/hal-engine-conversation-list/spec.md#over-the-websocket-protocol)
  it('accepts list_sessions pagination and rejects malformed fields', () => {
    const valid = validateMessage({
      type: 'list_sessions',
      limit: 10,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
      userId: 'another-user',
    });
    expect({valid, bare: validateMessage({type: 'list_sessions'})}).toEqual({
      valid: {
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 10,
          before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 's1'},
        },
      },
      bare: {valid: true, data: {type: 'list_sessions'}},
    });

    for (const [field, value] of [
      ['limit', '10'],
      ['limit', -1],
      ['limit', 1.5],
      ['before', 'not-an-object'],
      ['before', {updatedAt: 'not-a-date', sessionId: 's1'}],
      ['before', {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}],
    ] as const) {
      const result = validateMessage({type: 'list_sessions', [field]: value});
      expect(result).toEqual({valid: false, error: expect.stringContaining(field)});
    }
  });

  it('rejects list_sessions limits outside the protocol range', () => {
    expect([0, 201].map(limit => validateMessage({type: 'list_sessions', limit}))).toEqual([
      {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'},
      {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'},
    ]);
  });
